def calculate_speed(telemetry: dict) -> float:
    # Defensive field extraction with safe default
    dt = float(telemetry.get('dt', 1.0))
    distance = float(telemetry.get('distance', 0.0))
    # Safeguard against zero or negative delta-time
    if dt <= 0.0:
        return 0.0
    return round(distance / dt, 4)

