async function fetchUserData(userId: string): Promise<string> {
  try {
    const res = await fetch('/api/user/' + encodeURIComponent(userId));
    if (!res.ok) {
      throw new Error(`Network response not ok: ${res.status} ${res.statusText}`);
    }
    const data = await res.json();
    return data?.profile?.name || "Anonymous User";
  } catch (err: any) {
    console.error("fetchUserData error:", err);
    return "Unknown User";
  }
}
